WITH positive_conversations AS (SELECT COUNT(subq_3.positive_conversations_measure) AS positive_conversations, subq_3.day AS day, dim_agent.agent_type AS agent_type, dim_user.user_region AS location FROM (SELECT CASE WHEN csat_score >= 3 THEN ticket_id END AS positive_conversations_measure, dateTrunc('day', raised_at) AS day, final_agent_id AS agent, user_id AS user, final_agent_id AS agent, user_id AS user FROM fact_ticket_journey WHERE 1 = 1) AS subq_3 JOIN dim_agent AS dim_agent ON subq_3.agent = dim_agent.agent_id JOIN dim_user AS dim_user ON subq_3.user = dim_user.user_id GROUP BY day, agent_type, location), num_tickets_raised AS (SELECT subq_1.day AS day, COUNT(subq_1.num_tickets_raised_measure) AS num_tickets_raised, dim_agent.agent_type AS agent_type, dim_user.user_region AS location FROM (SELECT ticket_id AS num_tickets_raised_measure, dateTrunc('day', raised_at) AS day, final_agent_id AS agent, user_id AS user, final_agent_id AS agent, user_id AS user FROM fact_ticket_journey WHERE 1 = 1) AS subq_1 JOIN dim_agent AS dim_agent ON subq_1.agent = dim_agent.agent_id JOIN dim_user AS dim_user ON subq_1.user = dim_user.user_id GROUP BY day, agent_type, location), prefinal_cte AS (SELECT positive_conversations.day AS day, positive_conversations.agent_type AS agent_type, positive_conversations.location AS location, MAX(positive_conversations.positive_conversations) AS positive_conversations, MAX(num_tickets_raised.num_tickets_raised) AS num_tickets_raised FROM positive_conversations JOIN num_tickets_raised AS num_tickets_raised ON positive_conversations.day = num_tickets_raised.day AND positive_conversations.agent_type = num_tickets_raised.agent_type AND positive_conversations.location = num_tickets_raised.location GROUP BY day, agent_type, location) SELECT agent_type AS agent_type, location AS location, day AS day, MAX(positive_conversations / num_tickets_raised) AS CSAT_SCORE FROM prefinal_cte GROUP BY agent_type, location, day